inline const Entry* FindKey(const char* key) noexcept { if(key)for(const auto& e:kEntries)if(std::strcmp(e.key,key)==0)return &e;return nullptr; }
inline const Entry* FromNative(std::uint16_t id) noexcept { for(const auto& e:kEntries)if(e.count && e.monsterIds[0]==id)return &e;return nullptr; }
inline const char* Name(std::uint16_t id) noexcept { if(id==0x1156u)return "Dark Sandy";if(id==0x1157u)return "Dark Mindy";if(id==0x1155u)return "Dark Cindy";for(const auto& entry:kEntries)if(entry.monsterIds[0]==id)return entry.name;return "Monster"; }
